using System;using System.IO;using System.Linq;using System.Text;using System.Security.Cryptography;using NUnit.Framework;using UnityEditor;using UnityEditor.SceneManagement;using UnityEditor.AddressableAssets;using UnityEngine;using UnityEngine.SceneManagement;using UnityEngine.Tilemaps;using Rootborn.Game.Common;using Rootborn.Game.Placement;using Rootborn.Game.World;
namespace Rootborn.Tests.EditMode.Interiors{public sealed class UrbanStreetArtAssetTests{
public static string OriginalSignature(Scene scene){var text=new StringBuilder();foreach(var root in scene.GetRootGameObjects().Where(r=>r.name!="SchoolPlazaUrbanProps"&&r.name!="DreamJobWorkPoints"&&r.name!="BuildingReturnPoints"&&r.name!="TownResourcePoints"/*owner-approved 2026-11-07: wood resource trees for Mom's Gather Wood quest*/).OrderBy(r=>r.name)){foreach(var t in root.GetComponentsInChildren<Transform>(true).OrderBy(t=>PathOf(t)))text.AppendLine(PathOf(t)+" "+t.localToWorldMatrix+" "+t.gameObject.activeSelf);foreach(var c in root.GetComponentsInChildren<Collider2D>(true).OrderBy(c=>PathOf(c.transform))){text.AppendLine("collider "+PathOf(c.transform)+" "+c.GetType().Name+" "+c.enabled+" "+c.isTrigger+" "+c.offset);if(c is BoxCollider2D b)text.AppendLine("size "+b.size);}foreach(var map in root.GetComponentsInChildren<Tilemap>(true).OrderBy(m=>m.name))foreach(var cell in map.cellBounds.allPositionsWithin)if(map.HasTile(cell))text.AppendLine(map.name+" "+cell+" "+AssetDatabase.GetAssetPath(map.GetTile(cell))+" "+map.GetTransformMatrix(cell));foreach(var portal in root.GetComponentsInChildren<WorldPortal>(true).OrderBy(p=>PathOf(p.transform)))text.AppendLine("portal "+PathOf(portal.transform)+" "+portal.DestinationScene+" "+portal.DestinationSpawnId);}return BitConverter.ToString(SHA256.Create().ComputeHash(Encoding.UTF8.GetBytes(text.ToString()))).Replace("-","");}
static string PathOf(Transform t)=>t.parent==null?t.name:PathOf(t.parent)+"/"+t.name;
[TestCase("bench",2,96,96)][TestCase("lamp",1,48,192)][TestCase("bin",1,48,96)][TestCase("planter",2,96,96)]public void ReviewedFurnitureUsesRegisteredPixelSpriteAndExactFootprint(string name,int width,int px,int py){string path="Assets/Data/Interiors/Furniture/Urban31/Furniture_Urban31_"+name+".asset";var f=AssetDatabase.LoadAssetAtPath<FurnitureDefinition>(path);Assert.That(f,Is.Not.Null);Assert.That(f.StableId,Is.EqualTo("urban31."+name));Assert.That(f.FootprintCells.Count,Is.EqualTo(width));Assert.That(f.AllowedSurfaceIds,Does.Contain("town"));Assert.That(f.BlocksMovement,Is.True);var registry=AssetDatabase.LoadAssetAtPath<GameDataRegistry>("Assets/Data/Registry/GameDataRegistry.asset");Assert.That(registry.FurnitureDefinitions,Does.Contain(f));var tile=f.TileParts[0].Tile as Tile;Assert.That(tile,Is.Not.Null);var sprite=tile.sprite;Assert.That(sprite.rect.size,Is.EqualTo(new Vector2(px,py)));Assert.That(sprite.pivot,Is.EqualTo(new Vector2(24,24)));Assert.That(sprite.pixelsPerUnit,Is.EqualTo(48));var i=(TextureImporter)AssetImporter.GetAtPath(AssetDatabase.GetAssetPath(sprite));Assert.That(i.filterMode,Is.EqualTo(FilterMode.Point));Assert.That(i.mipmapEnabled,Is.False);Assert.That(i.textureCompression,Is.EqualTo(TextureImporterCompression.Uncompressed));var settings=AddressableAssetSettingsDefaultObject.Settings;foreach(var asset in new UnityEngine.Object[]{f,tile,sprite})Assert.That(settings.FindAssetEntry(AssetDatabase.AssetPathToGUID(AssetDatabase.GetAssetPath(asset))),Is.Not.Null);}
[Test]public void SavedPlazaUsesFourRegisteredTileReferencesAndSixCollisionCells(){var scene=EditorSceneManager.OpenScene("Assets/Scenes/Town.unity",OpenSceneMode.Additive);try{var root=scene.GetRootGameObjects().SingleOrDefault(g=>g.name=="SchoolPlazaUrbanProps");Assert.That(root,Is.Not.Null);string[] names={"bench","lamp","planter","bin"};Vector3Int[] cells={new Vector3Int(38,26,0),new Vector3Int(40,27,0),new Vector3Int(47,26,0),new Vector3Int(50,26,0)};var collision=root.GetComponentsInChildren<Tilemap>(true).Single(m=>m.name=="UrbanStreetCollision");int count=0;foreach(var cell in collision.cellBounds.allPositionsWithin)if(collision.HasTile(cell))count++;Assert.That(count,Is.EqualTo(6));Assert.That(collision.GetComponent<TilemapCollider2D>().enabled,Is.True);for(int n=0;n<4;n++){var f=AssetDatabase.LoadAssetAtPath<FurnitureDefinition>("Assets/Data/Interiors/Furniture/Urban31/Furniture_Urban31_"+names[n]+".asset");var map=root.GetComponentsInChildren<Tilemap>(true).Single(m=>m.name=="Urban_"+names[n]);Assert.That(map.GetTile(Vector3Int.zero),Is.SameAs(f.TileParts[0].Tile));Assert.That(map.transform.position,Is.EqualTo((Vector3)cells[n]));var r=map.GetComponent<TilemapRenderer>();Assert.That(r.mode,Is.EqualTo(TilemapRenderer.Mode.Individual));Assert.That(r.sortingOrder,Is.EqualTo(10000-Mathf.RoundToInt((cells[n].y+.5f)*48)));foreach(var foot in f.FootprintCells)Assert.That(collision.HasTile(cells[n]+new Vector3Int(foot.x,foot.y,0)),Is.True);}}finally{EditorSceneManager.CloseScene(scene,true);}}
[Test]public void OriginalTownObjectsMapsCollidersAndPortalsArePreserved(){var scene=EditorSceneManager.OpenScene("Assets/Scenes/Town.unity",OpenSceneMode.Additive);try{Assert.That(OriginalSignature(scene),Is.EqualTo(File.ReadAllText("output/design-comfy-20261031/evidence/urban-town-original-signature.txt").Trim()));}finally{EditorSceneManager.CloseScene(scene,true);}}
}}
